```verilog
`timescale 1ns/1ps

module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire [3:0] q;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Stimulus & self-checking:
    integer errors = 0;
    initial begin
        // Apply stimulus
        clk = 0;
        reset = 0;
        #10;

        // Test 1: Reset the counter to 1
        reset = 1;
        #10;
        if (q != 4'b0001) begin
            errors = errors + 1;
        end

        // Test 2: Count from 1 to 10
        reset = 0;
        for (int i = 1; i <= 10; i++) begin
            #10;
            clk = 1;
            #10;
            clk = 0;
            if (q != i) begin
                errors = errors + 1;
            end
        end

        // Check if all tests pass
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

    // Clock generation
    initial begin
        forever begin
            #10;
            clk = 1;
            #10;
            clk = 0;
        end
    end
endmodule
```

